    module alu_32bit (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    input wire [3:0] opcode,
    output reg [31:0] result,
    output reg zero,
    output reg overflow,
    output reg negative
);

    // Combinational logic for operations
    reg [31:0] temp_result;
    reg temp_overflow;

    // Shift amount: low 5 bits of B (standard RISC convention)
    wire [4:0] shift_amt;
    assign shift_amt = b[4:0];

    // Barrel shifter for SLL, SRL, SRA (unrolled for 5 stages)
    reg [31:0] sll_stage0, sll_stage1, sll_stage2, sll_stage3, sll_stage4;
    reg [31:0] srl_stage0, srl_stage1, srl_stage2, srl_stage3, srl_stage4;
    reg [31:0] sra_stage0, sra_stage1, sra_stage2, sra_stage3, sra_stage4;

    // SLL stages (logical left shift)
    always @(*) begin
        sll_stage0 = a;
        sll_stage1 = (shift_amt[0] ? {sll_stage0[30:0], 1'b0} : sll_stage0);
        sll_stage2 = (shift_amt[1] ? {sll_stage1[29:0], 2'b00} : sll_stage1);
        sll_stage3 = (shift_amt[2] ? {sll_stage2[27:0], 4'b0000} : sll_stage2);
        sll_stage4 = (shift_amt[3] ? {sll_stage3[23:0], 8'b00000000} : sll_stage3);
    end

    // SRL stages (logical right shift, zero-filled)
    always @(*) begin
        srl_stage0 = a;
        srl_stage1 = (shift_amt[0] ? {1'b0, srl_stage0[31:1]} : srl_stage0);
        srl_stage2 = (shift_amt[1] ? {2'b00, srl_stage1[31:2]} : srl_stage1);
        srl_stage3 = (shift_amt[2] ? {4'b0000, srl_stage2[31:4]} : srl_stage2);
        srl_stage4 = (shift_amt[3] ? {8'b00000000, srl_stage3[31:8]} : srl_stage3);
    end

    // SRA stages (arithmetic right shift, sign-extended)
    always @(*) begin
        sra_stage0 = a;
        sra_stage1 = (shift_amt[0] ? {{1{a[31]}}, sra_stage0[31:1]} : sra_stage0);
        sra_stage2 = (shift_amt[1] ? {{2{a[31]}}, sra_stage1[31:2]} : sra_stage1);
        sra_stage3 = (shift_amt[2] ? {{4{a[31]}}, sra_stage2[31:4]} : sra_stage2);
        sra_stage4 = (shift_amt[3] ? {{8{a[31]}}, sra_stage3[31:8]} : sra_stage3);
    end

    // Final shift results
    reg [31:0] sll_result, srl_result, sra_result;

    always @(*) begin
        sll_result = sll_stage4;
        srl_result = srl_stage4;
        sra_result = sra_stage4;
    end

    // Main operation selection logic
    always @(*) begin
        temp_overflow = 1'b0;
        case (opcode)
            4'b0000: begin // ADD
                temp_result = a + b;
                // Signed overflow: A[31]==B[31] and result[31] != A[31]
                temp_overflow = (a[31] & b[31] & ~temp_result[31]) |
                                (~a[31] & ~b[31] & temp_result[31]);
            end
            4'b0001: begin // SUB
                temp_result = a - b;
                // Signed overflow: A[31] != B[31] and result[31] != A[31]
                temp_overflow = (a[31] & ~b[31] & ~temp_result[31]) |
                                (~a[31] & b[31] & temp_result[31]);
            end
            4'b0010: temp_result = a & b;  // AND
            4'b0011: temp_result = a | b;  // OR
            4'b0100: temp_result = a ^ b;  // XOR
            4'b0101: temp_result = sll_result;  // SLL
            4'b0110: temp_result = srl_result;  // SRL
            4'b0111: temp_result = sra_result;  // SRA
            4'b1000: temp_result = ({1'b0, a} < {1'b0, b}) ? 32'b1 : 32'b0;  // SLT (signed)
            4'b1001: temp_result = (a < b) ? 32'b1 : 32'b0;  // SLTU (unsigned)
            default: temp_result = 32'b0;
        endcase
    end

    // Sequential logic for output registers
    always @(posedge clk) begin
        if (rst) begin
            result <= 32'b0;
            zero <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else begin
            result <= temp_result;
            zero <= (temp_result == 32'b0);
            overflow <= temp_overflow;
            negative <= temp_result[31];
        end
    end

